using System.Data;
using System.Text.Json;
using Ams.Application.Abstractions.Persistence;
using Dapper;
using Microsoft.Data.SqlClient;

namespace Ams.Worker.Intelligence;

public sealed class IntelligenceWorkerProcessor(ISqlConnectionFactory connectionFactory,ILogger<IntelligenceWorkerProcessor> logger)
{
    public async Task<IntelligenceWorkerSettings> GetSettingsAsync(CancellationToken cancellationToken)
    {
        const string sql="""SELECT SettingKey,COALESCE(SettingValue,DefaultValue) SettingValue FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND ScopeCode=N'Platform' AND ModuleCode=N'Intelligence' AND IsDeleted=0;""";using var connection=await connectionFactory.CreateOpenConnectionAsync(cancellationToken);var values=(await connection.QueryAsync<SettingRow>(new CommandDefinition(sql,cancellationToken:cancellationToken))).ToDictionary(x=>x.SettingKey,x=>x.SettingValue,StringComparer.OrdinalIgnoreCase);int Read(string key,int fallback)=>int.TryParse(values.GetValueOrDefault(key),out var value)?value:fallback;return new(Math.Clamp(Read("Intelligence.Recommendation.WorkerBatchSize",20),1,100),Math.Clamp(Read("Intelligence.Recommendation.WorkerIntervalSeconds",10),1,300),Math.Clamp(Read("Intelligence.Recommendation.LeaseSeconds",300),30,1800),Math.Clamp(Read("Intelligence.Evaluation.WorkerIntervalMinutes",15),1,1440),Math.Clamp(Read("Intelligence.Search.IndexIntervalMinutes",10),1,1440),Math.Clamp(Read("Intelligence.Platform.WorkerBatchSize",25),1,100),Math.Clamp(Read("Intelligence.Platform.WorkerIntervalSeconds",30),5,3600),Math.Clamp(Read("Intelligence.Platform.LeaseSeconds",300),30,1800));
    }

    public async Task<int> SynchronizePlatformProjectionsAsync(CancellationToken cancellationToken)
    {
        const string sql="""
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lockResult INT;
EXEC @lockResult=sys.sp_getapplock @Resource=N'AI.PlatformProjection.Synchronize',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=0;
IF @lockResult<0 BEGIN ROLLBACK TRANSACTION; THROW 51000,'Intelligence platform projection synchronization is already running.',1; END;
DECLARE @changed INT=0;
DECLARE @WorkflowDelayDays INT=COALESCE(TRY_CONVERT(INT,(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Workflow.DelayDays' AND IsDeleted=0 ORDER BY CASE WHEN TenantId IS NULL THEN 1 ELSE 0 END)),7);
DECLARE @DefaultDueDays INT=COALESCE(TRY_CONVERT(INT,(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Signal.DefaultDueDays' AND IsDeleted=0 ORDER BY CASE WHEN TenantId IS NULL THEN 1 ELSE 0 END)),2);

MERGE AI.EntityRelationship target USING
(
  SELECT submission.TenantId,N'SUBMISSION' SourceEntityTypeCode,submission.SubmissionId SourceEntityId,N'BELONGS_TO_ACCOUNT' RelationshipTypeCode,N'ACCOUNT' TargetEntityTypeCode,submission.AccountId TargetEntityId,N'Submissions' SourceModuleCode,N'Submissions.Submission.AccountId' SourceReference,CONVERT(decimal(5,4),1) Strength,submission.CreatedDateUtc EffectiveFromUtc,CAST(NULL AS DATETIME2) EffectiveToUtc
  FROM Submissions.Submission submission WHERE submission.IsDeleted=0
  UNION ALL
  SELECT claim.TenantId,N'CLAIM',claim.ClaimId,N'RELATED_TO_POLICY',N'POLICY',policy.PolicyId,N'Claims',N'Claims.Claim.PolicyNumber',CONVERT(decimal(5,4),1),claim.DateOfLoss,NULL
  FROM Claims.Claim claim JOIN Submissions.BoundPolicy policy ON policy.TenantId=claim.TenantId AND policy.PolicyNumber=claim.PolicyNumber AND policy.IsDeleted=0 WHERE claim.IsDeleted=0
  UNION ALL
  SELECT document.TenantId,N'DOCUMENT',document.DocumentId,N'ATTACHED_TO',UPPER(document.EntityName),document.EntityId,N'DMS',N'DMS.Document.EntityId',CONVERT(decimal(5,4),1),document.CreatedDateUtc,NULL
  FROM DMS.Document document WHERE document.IsDeleted=0 AND document.EntityId IS NOT NULL AND NULLIF(document.EntityName,N'') IS NOT NULL
) source ON target.TenantId=source.TenantId AND target.SourceEntityTypeCode=source.SourceEntityTypeCode AND target.SourceEntityId=source.SourceEntityId AND target.RelationshipTypeCode=source.RelationshipTypeCode AND target.TargetEntityTypeCode=source.TargetEntityTypeCode AND target.TargetEntityId=source.TargetEntityId
WHEN MATCHED THEN UPDATE SET SourceModuleCode=source.SourceModuleCode,SourceReference=source.SourceReference,Strength=source.Strength,EffectiveFromUtc=source.EffectiveFromUtc,EffectiveToUtc=source.EffectiveToUtc,LastSynchronizedDateUtc=SYSUTCDATETIME(),ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0
WHEN NOT MATCHED BY SOURCE AND target.SourceReference IN(N'Submissions.Submission.AccountId',N'Claims.Claim.PolicyNumber',N'DMS.Document.EntityId') AND target.IsDeleted=0 THEN UPDATE SET IsDeleted=1,EffectiveToUtc=COALESCE(target.EffectiveToUtc,SYSUTCDATETIME()),ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,SourceEntityTypeCode,SourceEntityId,RelationshipTypeCode,TargetEntityTypeCode,TargetEntityId,SourceModuleCode,SourceReference,Strength,EffectiveFromUtc,EffectiveToUtc,LastSynchronizedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.SourceEntityTypeCode,source.SourceEntityId,source.RelationshipTypeCode,source.TargetEntityTypeCode,source.TargetEntityId,source.SourceModuleCode,source.SourceReference,source.Strength,source.EffectiveFromUtc,source.EffectiveToUtc,SYSUTCDATETIME(),SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;

MERGE AI.BusinessSignal target USING
(
  SELECT submission.TenantId,capability.IntelligenceCapabilityId,N'SUBMISSION' EntityTypeCode,submission.SubmissionId EntityId,N'WORKFLOW_DELAY' SignalTypeCode,SYSUTCDATETIME() SignalDateUtc,N'MEDIUM' SeverityCode,CONVERT(decimal(18,6),DATEDIFF(DAY,COALESCE(submission.ModifiedDateUtc,submission.CreatedDateUtc),SYSUTCDATETIME())) Score,CONVERT(decimal(5,4),1) Confidence,N'Submission has not progressed' Title,CONCAT(N'No submission update has been recorded for ',DATEDIFF(DAY,COALESCE(submission.ModifiedDateUtc,submission.CreatedDateUtc),SYSUTCDATETIME()),N' days.') Summary,CONCAT(N'{"lastActivityDateUtc":"',CONVERT(nvarchar(33),COALESCE(submission.ModifiedDateUtc,submission.CreatedDateUtc),126),N'","ageDays":',DATEDIFF(DAY,COALESCE(submission.ModifiedDateUtc,submission.CreatedDateUtc),SYSUTCDATETIME()),N'}') EvidenceJson,N'REVIEW_SUBMISSION' RecommendedActionCode,N'OPEN' StatusCode,submission.AssignedToUserId,DATEADD(DAY,@DefaultDueDays,SYSUTCDATETIME()) DueDateUtc,CONCAT(N'WORKFLOW_DELAY:',CONVERT(nvarchar(36),submission.SubmissionId)) IdempotencyKey
  FROM Submissions.Submission submission CROSS JOIN AI.IntelligenceCapability capability WHERE capability.CapabilityCode=N'WORKFLOW_INTELLIGENCE' AND capability.TenantId IS NULL AND capability.IsDeleted=0 AND submission.IsDeleted=0 AND submission.Status NOT IN(N'Bound',N'Lost',N'Cancelled',N'Closed') AND DATEDIFF(DAY,COALESCE(submission.ModifiedDateUtc,submission.CreatedDateUtc),SYSUTCDATETIME())>=@WorkflowDelayDays
) source ON target.TenantId=source.TenantId AND target.IdempotencyKey=source.IdempotencyKey AND target.IsDeleted=0
WHEN MATCHED AND target.StatusCode IN(N'OPEN',N'REVIEW_REQUIRED',N'IN_PROGRESS') THEN UPDATE SET SignalDateUtc=source.SignalDateUtc,SeverityCode=source.SeverityCode,Score=source.Score,Summary=source.Summary,EvidenceJson=source.EvidenceJson,AssignedToUserId=source.AssignedToUserId,DueDateUtc=source.DueDateUtc,ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED BY SOURCE AND target.SignalTypeCode=N'WORKFLOW_DELAY' AND target.StatusCode IN(N'OPEN',N'REVIEW_REQUIRED',N'IN_PROGRESS') THEN UPDATE SET StatusCode=N'RESOLVED',ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,IntelligenceCapabilityId,EntityTypeCode,EntityId,SignalTypeCode,SignalDateUtc,SeverityCode,Score,Confidence,Title,Summary,EvidenceJson,RecommendedActionCode,StatusCode,AssignedToUserId,DueDateUtc,IdempotencyKey,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.IntelligenceCapabilityId,source.EntityTypeCode,source.EntityId,source.SignalTypeCode,source.SignalDateUtc,source.SeverityCode,source.Score,source.Confidence,source.Title,source.Summary,source.EvidenceJson,source.RecommendedActionCode,source.StatusCode,source.AssignedToUserId,source.DueDateUtc,source.IdempotencyKey,SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;

MERGE AI.IntelligenceFinding target USING
(
  SELECT submission.TenantId,capability.IntelligenceCapabilityId,policy.EnginePolicyId,N'SUBMISSION' EntityTypeCode,submission.SubmissionId EntityId,N'MISSING_REQUIRED_DOCUMENT' FindingTypeCode,N'HIGH' SeverityCode,N'REVIEW_REQUIRED' StatusCode,N'Required submission document is missing' Title,N'No active document is linked to this submission.' Summary,N'The document intelligence projection found no active DMS document linked to the submission. An authorized user must review the submission requirements before market or bind activity.' Explanation,CONVERT(decimal(18,6),1) Score,CONVERT(decimal(5,4),1) Confidence,CONVERT(nvarchar(50),policy.VersionNumber) RuleVersion,CONCAT(N'MISSING_DOCUMENT:',CONVERT(nvarchar(36),submission.SubmissionId)) IdempotencyKey
  FROM Submissions.Submission submission CROSS JOIN AI.IntelligenceCapability capability OUTER APPLY(SELECT TOP(1) EnginePolicyId,VersionNumber FROM AI.EnginePolicy p WHERE p.IntelligenceCapabilityId=capability.IntelligenceCapabilityId AND p.IsActive=1 AND p.IsDeleted=0 AND (p.TenantId=submission.TenantId OR p.TenantId IS NULL) ORDER BY CASE WHEN p.TenantId=submission.TenantId THEN 0 ELSE 1 END,p.VersionNumber DESC) policy
  WHERE capability.CapabilityCode=N'RISK_INTELLIGENCE' AND capability.TenantId IS NULL AND capability.IsDeleted=0 AND submission.IsDeleted=0 AND submission.Status IN(N'Ready for Marketing',N'Marketing',N'Quotes Requested',N'Binding') AND NOT EXISTS(SELECT 1 FROM DMS.Document document WHERE document.TenantId=submission.TenantId AND document.EntityId=submission.SubmissionId AND UPPER(document.EntityName)=N'SUBMISSION' AND document.IsDeleted=0)
) source ON target.TenantId=source.TenantId AND target.IdempotencyKey=source.IdempotencyKey AND target.IsDeleted=0
WHEN MATCHED AND target.StatusCode=N'RESOLVED' THEN UPDATE SET StatusCode=source.StatusCode,ResolvedDateUtc=NULL,ResolvedByUserId=NULL,ResolutionCode=NULL,ResolutionNotes=NULL,ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,IntelligenceCapabilityId,EnginePolicyId,EntityTypeCode,EntityId,FindingTypeCode,SeverityCode,StatusCode,Title,Summary,Explanation,Score,Confidence,RuleVersion,IdempotencyKey,DetectedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.IntelligenceCapabilityId,source.EnginePolicyId,source.EntityTypeCode,source.EntityId,source.FindingTypeCode,source.SeverityCode,source.StatusCode,source.Title,source.Summary,source.Explanation,source.Score,source.Confidence,source.RuleVersion,source.IdempotencyKey,SYSUTCDATETIME(),SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;

INSERT AI.FindingEvidence(TenantId,IntelligenceFindingId,EvidenceTypeCode,SourceModuleCode,SourceEntityTypeCode,SourceEntityId,SourceReference,Description,EvidenceValueJson,RelevanceScore,CreatedDateUtc,IsDeleted)
SELECT finding.TenantId,finding.IntelligenceFindingId,N'REQUIREMENT_CHECK',N'DMS',finding.EntityTypeCode,finding.EntityId,N'DMS.Document.EntityId',N'No active DMS document was linked to the submission when the configured risk requirement was evaluated.',N'{"documentCount":0}',1,SYSUTCDATETIME(),0 FROM AI.IntelligenceFinding finding WHERE finding.FindingTypeCode=N'MISSING_REQUIRED_DOCUMENT' AND finding.IsDeleted=0 AND NOT EXISTS(SELECT 1 FROM AI.FindingEvidence evidence WHERE evidence.TenantId=finding.TenantId AND evidence.IntelligenceFindingId=finding.IntelligenceFindingId AND evidence.EvidenceTypeCode=N'REQUIREMENT_CHECK' AND evidence.IsDeleted=0);
SET @changed+=@@ROWCOUNT;

MERGE Rules.RuleDefinition target USING
(
  SELECT recommendationRule.TenantId,CONCAT(N'RECOMMENDATION.',recommendationRule.RuleCode) RuleCode,recommendationRule.Name DisplayName,COALESCE(recommendationRule.Description,recommendationRule.Name) Description,N'RECOMMENDATION' RuleCategoryCode,recommendationRule.EntityTypeCode,N'AI' SourceModuleCode,recommendationRule.ConditionJson,recommendationRule.ActionJson OutcomeJson,CASE WHEN recommendationRule.Priority>=80 THEN N'HIGH' WHEN recommendationRule.Priority>=50 THEN N'MEDIUM' ELSE N'LOW' END SeverityCode,CONVERT(bit,0) StopsProcessing,recommendationRule.EffectiveFromUtc,recommendationRule.EffectiveToUtc,1 VersionNumber,recommendationRule.IsActive
  FROM AI.RecommendationRule recommendationRule WHERE recommendationRule.IsDeleted=0
) source ON target.TenantId=source.TenantId AND target.RuleCode=source.RuleCode AND target.VersionNumber=source.VersionNumber AND target.IsDeleted=0
WHEN MATCHED THEN UPDATE SET DisplayName=source.DisplayName,Description=source.Description,RuleCategoryCode=source.RuleCategoryCode,EntityTypeCode=source.EntityTypeCode,SourceModuleCode=source.SourceModuleCode,ConditionJson=source.ConditionJson,OutcomeJson=source.OutcomeJson,SeverityCode=source.SeverityCode,StopsProcessing=source.StopsProcessing,EffectiveFromUtc=source.EffectiveFromUtc,EffectiveToUtc=source.EffectiveToUtc,IsActive=source.IsActive,ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,RuleCode,DisplayName,Description,RuleCategoryCode,EntityTypeCode,SourceModuleCode,ConditionJson,OutcomeJson,SeverityCode,StopsProcessing,EffectiveFromUtc,EffectiveToUtc,VersionNumber,IsActive,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.RuleCode,source.DisplayName,source.Description,source.RuleCategoryCode,source.EntityTypeCode,source.SourceModuleCode,source.ConditionJson,source.OutcomeJson,source.SeverityCode,source.StopsProcessing,source.EffectiveFromUtc,source.EffectiveToUtc,source.VersionNumber,source.IsActive,SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;

MERGE Validation.ValidationDefinition target USING
(
  SELECT requirement.TenantId,CONCAT(N'COMPLIANCE.',requirement.RequirementCode) ValidationCode,requirement.DisplayName,requirement.Description,CASE requirement.RequirementTypeCode WHEN N'DOCUMENT' THEN N'DOCUMENT' WHEN N'REQUIRED_FIELD' THEN N'REQUIRED_FIELD' WHEN N'STATE' THEN N'STATE' WHEN N'CARRIER' THEN N'CARRIER' ELSE N'BUSINESS' END ValidatorTypeCode,requirement.EntityTypeCode,N'AI' SourceModuleCode,requirement.JurisdictionCode,requirement.CarrierId,requirement.LineOfBusinessCode,requirement.EvaluationJson ConditionJson,CONCAT(N'{"message":"',STRING_ESCAPE(requirement.Description,N'json'),N'","requirementCode":"',STRING_ESCAPE(requirement.RequirementCode,N'json'),N'"}') FailureJson,requirement.SeverityCode,requirement.BlocksTransaction IsBlocking,requirement.CanBeWaived,requirement.WaiverPermissionCode,requirement.EffectiveFromUtc,requirement.EffectiveToUtc,requirement.VersionNumber,requirement.IsActive
  FROM AI.ComplianceRequirement requirement WHERE requirement.IsDeleted=0
) source ON target.TenantId=source.TenantId AND target.ValidationCode=source.ValidationCode AND target.VersionNumber=source.VersionNumber AND target.IsDeleted=0
WHEN MATCHED THEN UPDATE SET DisplayName=source.DisplayName,Description=source.Description,ValidatorTypeCode=source.ValidatorTypeCode,EntityTypeCode=source.EntityTypeCode,SourceModuleCode=source.SourceModuleCode,JurisdictionCode=source.JurisdictionCode,CarrierId=source.CarrierId,LineOfBusinessCode=source.LineOfBusinessCode,ConditionJson=source.ConditionJson,FailureJson=source.FailureJson,SeverityCode=source.SeverityCode,IsBlocking=source.IsBlocking,CanBeWaived=source.CanBeWaived,WaiverPermissionCode=source.WaiverPermissionCode,EffectiveFromUtc=source.EffectiveFromUtc,EffectiveToUtc=source.EffectiveToUtc,IsActive=source.IsActive,ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,ValidationCode,DisplayName,Description,ValidatorTypeCode,EntityTypeCode,SourceModuleCode,JurisdictionCode,CarrierId,LineOfBusinessCode,ConditionJson,FailureJson,SeverityCode,IsBlocking,CanBeWaived,WaiverPermissionCode,EffectiveFromUtc,EffectiveToUtc,VersionNumber,IsActive,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.ValidationCode,source.DisplayName,source.Description,source.ValidatorTypeCode,source.EntityTypeCode,source.SourceModuleCode,source.JurisdictionCode,source.CarrierId,source.LineOfBusinessCode,source.ConditionJson,source.FailureJson,source.SeverityCode,source.IsBlocking,source.CanBeWaived,source.WaiverPermissionCode,source.EffectiveFromUtc,source.EffectiveToUtc,source.VersionNumber,source.IsActive,SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;
COMMIT TRANSACTION;
SELECT @changed;
""";
        return await ExecuteSynchronizationAsync(sql,"platform projection",180,cancellationToken);
    }

    public async Task<int> SynchronizeDecisionAndDiscoveryAsync(CancellationToken cancellationToken)
    {
        const string sql="""
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lockResult INT;
EXEC @lockResult=sys.sp_getapplock @Resource=N'AI.DecisionDiscovery.Synchronize',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=0;
IF @lockResult<0 BEGIN ROLLBACK TRANSACTION; THROW 51000,'Decision and discovery synchronization is already running.',1; END;
DECLARE @changed INT=0;
DECLARE @ExactScore decimal(5,4)=COALESCE(TRY_CONVERT(decimal(5,4),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Similarity.ExactAttributeScore' AND IsDeleted=0 ORDER BY CASE WHEN TenantId IS NULL THEN 1 ELSE 0 END)),.90);
DECLARE @PrimaryScore decimal(5,4)=COALESCE(TRY_CONVERT(decimal(5,4),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Similarity.PrimaryAttributeScore' AND IsDeleted=0 ORDER BY CASE WHEN TenantId IS NULL THEN 1 ELSE 0 END)),.80);
DECLARE @RelatedScore decimal(5,4)=COALESCE(TRY_CONVERT(decimal(5,4),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Similarity.RelatedAttributeScore' AND IsDeleted=0 ORDER BY CASE WHEN TenantId IS NULL THEN 1 ELSE 0 END)),.70);
DECLARE @FixedAmountTolerance decimal(18,2)=COALESCE(TRY_CONVERT(decimal(18,2),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Similarity.FixedAmountTolerance' AND IsDeleted=0 ORDER BY CASE WHEN TenantId IS NULL THEN 1 ELSE 0 END)),25000);
DECLARE @SubmissionTolerancePercent decimal(9,4)=COALESCE(TRY_CONVERT(decimal(9,4),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Similarity.SubmissionAmountTolerancePercent' AND IsDeleted=0 ORDER BY CASE WHEN TenantId IS NULL THEN 1 ELSE 0 END)),.35);
DECLARE @ClaimTolerancePercent decimal(9,4)=COALESCE(TRY_CONVERT(decimal(9,4),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Similarity.ClaimAmountTolerancePercent' AND IsDeleted=0 ORDER BY CASE WHEN TenantId IS NULL THEN 1 ELSE 0 END)),.50);
DECLARE @SimilarityExpirationDays int=COALESCE(TRY_CONVERT(int,(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Similarity.ExpirationDays' AND IsDeleted=0 ORDER BY CASE WHEN TenantId IS NULL THEN 1 ELSE 0 END)),7);

MERGE AI.EntityRelationship target USING
(
  SELECT policy.TenantId,N'ACCOUNT' SourceEntityTypeCode,policy.AccountId SourceEntityId,N'HAS_POLICY' RelationshipTypeCode,N'POLICY' TargetEntityTypeCode,policy.PolicyId TargetEntityId,N'Policy' SourceModuleCode,N'Submissions.BoundPolicy.AccountId' SourceReference,CONVERT(decimal(5,4),1) Strength,policy.EffectiveDate EffectiveFromUtc,policy.ExpirationDate EffectiveToUtc FROM Submissions.BoundPolicy policy WHERE policy.IsDeleted=0
  UNION ALL
  SELECT relationship.TenantId,N'ACCOUNT',relationship.AccountId,UPPER(REPLACE(relationship.RelationshipType,N' ',N'_')),N'ACCOUNT',relationship.RelatedAccountId,N'Client',N'Client.AccountRelationship',CONVERT(decimal(5,4),1),relationship.CreatedDateUtc,NULL FROM Client.AccountRelationship relationship WHERE relationship.IsDeleted=0 AND relationship.IsActive=1
  UNION ALL
  SELECT bind.TenantId,N'SUBMISSION',bind.SubmissionId,N'HAS_BIND_TRANSACTION',N'BIND_TRANSACTION',bind.PolicyBindTransactionId,N'Submissions',N'Submissions.PolicyBindTransaction.SubmissionId',CONVERT(decimal(5,4),1),bind.CreatedDateUtc,NULL FROM Submissions.PolicyBindTransaction bind WHERE bind.IsDeleted=0
) source ON target.TenantId=source.TenantId AND target.SourceEntityTypeCode=source.SourceEntityTypeCode AND target.SourceEntityId=source.SourceEntityId AND target.RelationshipTypeCode=source.RelationshipTypeCode AND target.TargetEntityTypeCode=source.TargetEntityTypeCode AND target.TargetEntityId=source.TargetEntityId
WHEN MATCHED THEN UPDATE SET SourceModuleCode=source.SourceModuleCode,SourceReference=source.SourceReference,Strength=source.Strength,EffectiveFromUtc=source.EffectiveFromUtc,EffectiveToUtc=source.EffectiveToUtc,LastSynchronizedDateUtc=SYSUTCDATETIME(),ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0
WHEN NOT MATCHED BY SOURCE AND target.SourceReference IN(N'Submissions.BoundPolicy.AccountId',N'Client.AccountRelationship',N'Submissions.PolicyBindTransaction.SubmissionId') AND target.IsDeleted=0 THEN UPDATE SET IsDeleted=1,EffectiveToUtc=COALESCE(target.EffectiveToUtc,SYSUTCDATETIME()),ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,SourceEntityTypeCode,SourceEntityId,RelationshipTypeCode,TargetEntityTypeCode,TargetEntityId,SourceModuleCode,SourceReference,Strength,EffectiveFromUtc,EffectiveToUtc,LastSynchronizedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.SourceEntityTypeCode,source.SourceEntityId,source.RelationshipTypeCode,source.TargetEntityTypeCode,source.TargetEntityId,source.SourceModuleCode,source.SourceReference,source.Strength,source.EffectiveFromUtc,source.EffectiveToUtc,SYSUTCDATETIME(),SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;

MERGE AI.EntitySimilarity target USING
(
  SELECT source.TenantId,N'SUBMISSION' EntityTypeCode,source.SubmissionId SourceEntityId,candidate.SubmissionId SimilarEntityId,N'SUBMISSION_SHARED_ATTRIBUTES' SimilarityModelCode,N'1.0' SimilarityModelVersion,CONVERT(decimal(5,4),CASE WHEN source.LineOfBusiness=candidate.LineOfBusiness AND source.Priority=candidate.Priority THEN @ExactScore WHEN source.LineOfBusiness=candidate.LineOfBusiness THEN @PrimaryScore ELSE @RelatedScore END) SimilarityScore,CONCAT(N'{"lineOfBusiness":"',STRING_ESCAPE(source.LineOfBusiness,'json'),N'","sharedPriority":',CASE WHEN source.Priority=candidate.Priority THEN N'true' ELSE N'false' END,N',"premiumDifference":',ABS(COALESCE(source.TargetPremium,0)-COALESCE(candidate.TargetPremium,0)),N'}') FeatureEvidenceJson
  FROM Submissions.Submission source JOIN Submissions.Submission candidate ON candidate.TenantId=source.TenantId AND candidate.SubmissionId<>source.SubmissionId AND candidate.IsDeleted=0 AND candidate.LineOfBusiness=source.LineOfBusiness AND ABS(COALESCE(source.TargetPremium,0)-COALESCE(candidate.TargetPremium,0))<=CASE WHEN COALESCE(source.TargetPremium,0)=0 THEN @FixedAmountTolerance ELSE ABS(source.TargetPremium)*@SubmissionTolerancePercent END WHERE source.IsDeleted=0
  UNION ALL
  SELECT source.TenantId,N'ACCOUNT',source.AccountId,candidate.AccountId,N'ACCOUNT_SHARED_ATTRIBUTES',N'1.0',CONVERT(decimal(5,4),CASE WHEN source.Industry=candidate.Industry AND source.SegmentCode=candidate.SegmentCode THEN @ExactScore WHEN source.Industry=candidate.Industry THEN @PrimaryScore ELSE @RelatedScore END),CONCAT(N'{"industry":"',STRING_ESCAPE(COALESCE(source.Industry,N''),'json'),N'","sharedSegment":',CASE WHEN source.SegmentCode=candidate.SegmentCode THEN N'true' ELSE N'false' END,N'}') FROM Client.Account source JOIN Client.Account candidate ON candidate.TenantId=source.TenantId AND candidate.AccountId<>source.AccountId AND candidate.IsDeleted=0 AND (candidate.Industry=source.Industry OR candidate.SegmentCode=source.SegmentCode) WHERE source.IsDeleted=0
  UNION ALL
  SELECT source.TenantId,N'CLAIM',source.ClaimId,candidate.ClaimId,N'CLAIM_SHARED_LOSS_ATTRIBUTES',N'1.0',CONVERT(decimal(5,4),CASE WHEN source.Lob=candidate.Lob AND source.LossType=candidate.LossType THEN @ExactScore WHEN source.Lob=candidate.Lob THEN @PrimaryScore ELSE @RelatedScore END),CONCAT(N'{"lineOfBusiness":"',STRING_ESCAPE(COALESCE(source.Lob,N''),'json'),N'","lossType":"',STRING_ESCAPE(COALESCE(source.LossType,N''),'json'),N'","incurredDifference":',ABS(COALESCE(source.TotalIncurred,0)-COALESCE(candidate.TotalIncurred,0)),N'}') FROM Claims.Claim source JOIN Claims.Claim candidate ON candidate.TenantId=source.TenantId AND candidate.ClaimId<>source.ClaimId AND candidate.IsDeleted=0 AND (candidate.Lob=source.Lob OR candidate.LossType=source.LossType) AND ABS(COALESCE(source.TotalIncurred,0)-COALESCE(candidate.TotalIncurred,0))<=CASE WHEN COALESCE(source.TotalIncurred,0)=0 THEN @FixedAmountTolerance ELSE ABS(source.TotalIncurred)*@ClaimTolerancePercent END WHERE source.IsDeleted=0
) source ON target.TenantId=source.TenantId AND target.EntityTypeCode=source.EntityTypeCode AND target.SourceEntityId=source.SourceEntityId AND target.SimilarEntityId=source.SimilarEntityId AND target.SimilarityModelCode=source.SimilarityModelCode AND target.SimilarityModelVersion=source.SimilarityModelVersion
WHEN MATCHED THEN UPDATE SET SimilarityScore=source.SimilarityScore,FeatureEvidenceJson=source.FeatureEvidenceJson,CalculatedDateUtc=SYSUTCDATETIME(),ExpiresDateUtc=DATEADD(DAY,@SimilarityExpirationDays,SYSUTCDATETIME()),ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0
WHEN NOT MATCHED BY SOURCE AND target.SimilarityModelCode IN(N'SUBMISSION_SHARED_ATTRIBUTES',N'ACCOUNT_SHARED_ATTRIBUTES',N'CLAIM_SHARED_LOSS_ATTRIBUTES') AND target.IsDeleted=0 THEN UPDATE SET IsDeleted=1,ExpiresDateUtc=SYSUTCDATETIME(),ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,EntityTypeCode,SourceEntityId,SimilarEntityId,SimilarityModelCode,SimilarityModelVersion,SimilarityScore,FeatureEvidenceJson,CalculatedDateUtc,ExpiresDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.EntityTypeCode,source.SourceEntityId,source.SimilarEntityId,source.SimilarityModelCode,source.SimilarityModelVersion,source.SimilarityScore,source.FeatureEvidenceJson,SYSUTCDATETIME(),DATEADD(DAY,@SimilarityExpirationDays,SYSUTCDATETIME()),SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;

MERGE AI.IntelligenceFinding target USING
(
  SELECT validation.TenantId,capability.IntelligenceCapabilityId,policy.EnginePolicyId,N'BIND_TRANSACTION' EntityTypeCode,validation.PolicyBindTransactionId EntityId,CASE WHEN validation.RequirementTypeCode LIKE N'%Document%' THEN N'MISSING_REQUIRED_DOCUMENT' ELSE N'BIND_REQUIREMENT_FAILED' END FindingTypeCode,CASE WHEN validation.IsBlocking=1 THEN N'HIGH' ELSE N'MEDIUM' END SeverityCode,N'REVIEW_REQUIRED' StatusCode,validation.RequirementName Title,COALESCE(validation.Message,N'Configured bind validation did not pass.') Summary,CONCAT(N'Bind requirement ',validation.RequirementCode,N' is ',validation.StatusCode,N'. The result is sourced from Submissions.BindValidationResult and must be resolved or waived through the authoritative bind workflow.') Explanation,CONVERT(decimal(18,6),CASE WHEN validation.IsBlocking=1 THEN 100 ELSE 50 END) Score,CONVERT(decimal(5,4),1) Confidence,CONVERT(nvarchar(50),policy.VersionNumber) RuleVersion,CONCAT(N'BIND_VALIDATION:',CONVERT(nvarchar(36),validation.BindValidationResultId)) IdempotencyKey
  FROM Submissions.BindValidationResult validation CROSS JOIN AI.IntelligenceCapability capability OUTER APPLY(SELECT TOP(1) EnginePolicyId,VersionNumber FROM AI.EnginePolicy p WHERE p.IntelligenceCapabilityId=capability.IntelligenceCapabilityId AND p.IsActive=1 AND p.IsDeleted=0 AND (p.TenantId=validation.TenantId OR p.TenantId IS NULL) ORDER BY CASE WHEN p.TenantId=validation.TenantId THEN 0 ELSE 1 END,p.VersionNumber DESC) policy WHERE capability.CapabilityCode=N'COMPLIANCE_INTELLIGENCE' AND capability.TenantId IS NULL AND capability.IsDeleted=0 AND validation.StatusCode IN(N'Failed',N'Pending') AND validation.IsDeleted=0
) source ON target.TenantId=source.TenantId AND target.IdempotencyKey=source.IdempotencyKey AND target.IsDeleted=0
WHEN MATCHED AND target.StatusCode<>N'RESOLVED' THEN UPDATE SET SeverityCode=source.SeverityCode,StatusCode=source.StatusCode,Summary=source.Summary,Explanation=source.Explanation,Score=source.Score,RuleVersion=source.RuleVersion,ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED BY SOURCE AND target.IdempotencyKey LIKE N'BIND_VALIDATION:%' AND target.StatusCode IN(N'OPEN',N'REVIEW_REQUIRED',N'IN_REVIEW') THEN UPDATE SET StatusCode=N'RESOLVED',ResolvedDateUtc=SYSUTCDATETIME(),ResolutionCode=N'AUTO_RESOLVED',ResolutionNotes=N'The authoritative bind validation is no longer failed or pending.',ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,IntelligenceCapabilityId,EnginePolicyId,EntityTypeCode,EntityId,FindingTypeCode,SeverityCode,StatusCode,Title,Summary,Explanation,Score,Confidence,RuleVersion,IdempotencyKey,DetectedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.IntelligenceCapabilityId,source.EnginePolicyId,source.EntityTypeCode,source.EntityId,source.FindingTypeCode,source.SeverityCode,source.StatusCode,source.Title,source.Summary,source.Explanation,source.Score,source.Confidence,source.RuleVersion,source.IdempotencyKey,SYSUTCDATETIME(),SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;

MERGE AI.IntelligenceFinding target USING
(
  SELECT claim.TenantId,capability.IntelligenceCapabilityId,policy.EnginePolicyId,N'CLAIM' EntityTypeCode,claim.ClaimId EntityId,N'LARGE_LOSS' FindingTypeCode,N'HIGH' SeverityCode,N'OPEN' StatusCode,N'Large incurred loss requires review' Title,CONCAT(N'Total incurred ',FORMAT(claim.TotalIncurred,'C',N'en-US'),N' exceeds the configured advisory threshold.') Summary,N'This is an advisory large-loss pattern sourced from Claims.Claim. It does not determine coverage, fraud, liability, or claim disposition.' Explanation,CONVERT(decimal(18,6),claim.TotalIncurred) Score,CONVERT(decimal(5,4),1) Confidence,CONVERT(nvarchar(50),policy.VersionNumber) RuleVersion,CONCAT(N'LARGE_LOSS:',CONVERT(nvarchar(36),claim.ClaimId),N':',CONVERT(nvarchar(40),threshold.Threshold)) IdempotencyKey
  FROM Claims.Claim claim CROSS APPLY(SELECT COALESCE(TRY_CONVERT(decimal(18,2),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey=N'Intelligence.Risk.LargeLossThreshold' AND IsDeleted=0 ORDER BY CASE WHEN TenantId=claim.TenantId THEN 0 ELSE 1 END)),100000) Threshold) threshold CROSS JOIN AI.IntelligenceCapability capability OUTER APPLY(SELECT TOP(1) EnginePolicyId,VersionNumber FROM AI.EnginePolicy p WHERE p.IntelligenceCapabilityId=capability.IntelligenceCapabilityId AND p.IsActive=1 AND p.IsDeleted=0 AND (p.TenantId=claim.TenantId OR p.TenantId IS NULL) ORDER BY CASE WHEN p.TenantId=claim.TenantId THEN 0 ELSE 1 END,p.VersionNumber DESC) policy WHERE capability.CapabilityCode=N'RISK_INTELLIGENCE' AND capability.TenantId IS NULL AND capability.IsDeleted=0 AND claim.IsDeleted=0 AND claim.TotalIncurred>=threshold.Threshold
) source ON target.TenantId=source.TenantId AND target.IdempotencyKey=source.IdempotencyKey AND target.IsDeleted=0
WHEN MATCHED AND target.StatusCode<>N'RESOLVED' THEN UPDATE SET Score=source.Score,Summary=source.Summary,RuleVersion=source.RuleVersion,ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED BY SOURCE AND target.FindingTypeCode=N'LARGE_LOSS' AND target.StatusCode IN(N'OPEN',N'REVIEW_REQUIRED',N'IN_REVIEW') THEN UPDATE SET StatusCode=N'RESOLVED',ResolvedDateUtc=SYSUTCDATETIME(),ResolutionCode=N'AUTO_RESOLVED',ResolutionNotes=N'The authoritative claim no longer meets the configured large-loss threshold.',ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,IntelligenceCapabilityId,EnginePolicyId,EntityTypeCode,EntityId,FindingTypeCode,SeverityCode,StatusCode,Title,Summary,Explanation,Score,Confidence,RuleVersion,IdempotencyKey,DetectedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.IntelligenceCapabilityId,source.EnginePolicyId,source.EntityTypeCode,source.EntityId,source.FindingTypeCode,source.SeverityCode,source.StatusCode,source.Title,source.Summary,source.Explanation,source.Score,source.Confidence,source.RuleVersion,source.IdempotencyKey,SYSUTCDATETIME(),SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;
COMMIT TRANSACTION;
SELECT @changed;
""";
        return await ExecuteSynchronizationAsync(sql,"decision and discovery",240,cancellationToken);
    }

    public async Task<int> SynchronizeBusinessIntelligenceAsync(CancellationToken cancellationToken)
    {
        const string sql="""
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lockResult INT;
EXEC @lockResult=sys.sp_getapplock @Resource=N'AI.BusinessIntelligence.Synchronize',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=0;
IF @lockResult<0 BEGIN ROLLBACK TRANSACTION; THROW 51000,'Business intelligence synchronization is already running.',1; END;
DECLARE @changed INT=0;
DECLARE @ApprovalDelayDays INT=COALESCE(TRY_CONVERT(INT,(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND SettingKey=N'Intelligence.Workflow.ApprovalDelayDays' AND IsDeleted=0)),2);
DECLARE @HighApprovalDays INT=COALESCE(TRY_CONVERT(INT,(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND SettingKey=N'Intelligence.Workflow.HighSeverityApprovalDays' AND IsDeleted=0)),5);
DECLARE @RenewalDays INT=COALESCE(TRY_CONVERT(INT,(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND SettingKey=N'Intelligence.Renewal.ReadinessDays' AND IsDeleted=0)),90);
DECLARE @RenewalHighRiskProbability DECIMAL(5,2)=COALESCE(TRY_CONVERT(DECIMAL(5,2),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND SettingKey=N'Intelligence.Renewal.HighRiskRetentionProbability' AND IsDeleted=0)),50);
DECLARE @RenewalMediumRiskProbability DECIMAL(5,2)=COALESCE(TRY_CONVERT(DECIMAL(5,2),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND SettingKey=N'Intelligence.Renewal.MediumRiskRetentionProbability' AND IsDeleted=0)),70);
DECLARE @ClaimThreshold DECIMAL(18,2)=COALESCE(TRY_CONVERT(DECIMAL(18,2),(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND SettingKey=N'Intelligence.Claims.ReviewThreshold' AND IsDeleted=0)),100000);
DECLARE @ProducerDays INT=COALESCE(TRY_CONVERT(INT,(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND SettingKey=N'Intelligence.Producer.FollowUpDays' AND IsDeleted=0)),5);
DECLARE @CustomerGapDays INT=COALESCE(TRY_CONVERT(INT,(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND SettingKey=N'Intelligence.Customer.CommunicationGapDays' AND IsDeleted=0)),30);
DECLARE @DefaultDueDays INT=COALESCE(TRY_CONVERT(INT,(SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND SettingKey=N'Intelligence.Signal.DefaultDueDays' AND IsDeleted=0)),2);

MERGE AI.BusinessSignal target USING
(
  SELECT approval.TenantId,capability.IntelligenceCapabilityId,N'BIND_TRANSACTION' EntityTypeCode,approval.PolicyBindTransactionId EntityId,N'FREQUENT_APPROVAL_POINT' SignalTypeCode,SYSUTCDATETIME() SignalDateUtc,CASE WHEN DATEDIFF(DAY,approval.RequestedDateUtc,SYSUTCDATETIME())>=@HighApprovalDays THEN N'HIGH' ELSE N'MEDIUM' END SeverityCode,CONVERT(decimal(18,6),DATEDIFF(DAY,approval.RequestedDateUtc,SYSUTCDATETIME())) Score,CONVERT(decimal(5,4),1) Confidence,N'Bind approval is waiting' Title,CONCAT(N'Approval reason ',approval.ApprovalReasonCode,N' has been pending for ',DATEDIFF(DAY,approval.RequestedDateUtc,SYSUTCDATETIME()),N' days.') Summary,CONCAT(N'{"source":"Submissions.BindApproval","approvalReasonCode":"',STRING_ESCAPE(approval.ApprovalReasonCode,'json'),N'","requestedDateUtc":"',CONVERT(nvarchar(33),approval.RequestedDateUtc,126),N'"}') EvidenceJson,N'REVIEW_BIND_APPROVAL' RecommendedActionCode,N'OPEN' StatusCode,approval.AssignedApproverUserId AssignedToUserId,DATEADD(DAY,@DefaultDueDays,SYSUTCDATETIME()) DueDateUtc,CONCAT(N'WORKFLOW_APPROVAL:',CONVERT(nvarchar(36),approval.BindApprovalId)) IdempotencyKey
  FROM Submissions.BindApproval approval CROSS JOIN AI.IntelligenceCapability capability WHERE capability.CapabilityCode=N'WORKFLOW_INTELLIGENCE' AND capability.TenantId IS NULL AND capability.IsDeleted=0 AND approval.StatusCode=N'Pending' AND approval.IsDeleted=0 AND DATEDIFF(DAY,approval.RequestedDateUtc,SYSUTCDATETIME())>=@ApprovalDelayDays
  UNION ALL
  SELECT renewal.TenantId,capability.IntelligenceCapabilityId,N'RENEWAL_CASE',renewal.RetentionCaseId,N'RENEWAL_PRIORITY',SYSUTCDATETIME(),CASE WHEN renewal.IsAtRisk=1 OR renewal.RetentionProbability<@RenewalHighRiskProbability THEN N'HIGH' WHEN renewal.RetentionProbability<@RenewalMediumRiskProbability THEN N'MEDIUM' ELSE N'LOW' END,CONVERT(decimal(18,6),renewal.RiskScore),CONVERT(decimal(5,4),1),N'Renewal requires prioritized preparation',CONCAT(N'Policy ',renewal.PolicyNumber,N' expires ',CONVERT(nvarchar(10),renewal.ExpirationDate,23),N'; retention probability ',renewal.RetentionProbability,N'%. ',COALESCE(renewal.RiskDrivers,N'')),CONCAT(N'{"source":"Renewal.RetentionCase","retentionProbability":',renewal.RetentionProbability,N',"riskScore":',renewal.RiskScore,N',"stage":"',STRING_ESCAPE(renewal.Stage,'json'),N'","outreachStatus":"',STRING_ESCAPE(renewal.OutreachStatus,'json'),N'"}'),N'OPEN_RENEWAL_CASE',N'OPEN',renewal.AssignedToUserId,COALESCE(renewal.NextActionDueDate,DATEADD(DAY,@DefaultDueDays,CONVERT(date,SYSUTCDATETIME()))),CONCAT(N'RENEWAL_PRIORITY:',CONVERT(nvarchar(36),renewal.RetentionCaseId),N':',CONVERT(char(8),renewal.ExpirationDate,112))
  FROM Renewal.RetentionCase renewal CROSS JOIN AI.IntelligenceCapability capability WHERE capability.CapabilityCode=N'RENEWAL_INTELLIGENCE' AND capability.TenantId IS NULL AND capability.IsDeleted=0 AND renewal.IsDeleted=0 AND renewal.IsSaved=0 AND renewal.ExpirationDate<=DATEADD(DAY,@RenewalDays,CONVERT(date,SYSUTCDATETIME()))
  UNION ALL
  SELECT claim.TenantId,capability.IntelligenceCapabilityId,N'CLAIM',claim.ClaimId,CASE WHEN link.ClaimId IS NULL THEN N'CLAIM_MISSING_DOCUMENTATION' ELSE N'CLAIM_RULE_ASSISTED_REVIEW' END,SYSUTCDATETIME(),CASE WHEN claim.TotalIncurred>=@ClaimThreshold OR claim.IsDisputed=1 THEN N'HIGH' ELSE N'MEDIUM' END,CONVERT(decimal(18,6),claim.TotalIncurred),CONVERT(decimal(5,4),1),CASE WHEN link.ClaimId IS NULL THEN N'Claim documentation review needed' ELSE N'Claim pattern requires adjuster review' END,CASE WHEN link.ClaimId IS NULL THEN N'No active claim document link is recorded.' ELSE N'One or more configured claim flags or large-loss characteristics require adjuster review; this is not a fraud or coverage decision.' END,CONCAT(N'{"source":"Claims.Claim","totalIncurred":',COALESCE(CONVERT(nvarchar(40),claim.TotalIncurred),N'0'),N',"isLitigation":',CASE WHEN claim.IsLitigation=1 THEN N'true' ELSE N'false' END,N',"isDisputed":',CASE WHEN claim.IsDisputed=1 THEN N'true' ELSE N'false' END,N',"isCatastrophe":',CASE WHEN claim.IsCatastrophe=1 THEN N'true' ELSE N'false' END,N',"documentLinked":',CASE WHEN link.ClaimId IS NULL THEN N'false' ELSE N'true' END,N'}'),N'REVIEW_CLAIM',N'OPEN',NULL,DATEADD(DAY,@DefaultDueDays,SYSUTCDATETIME()),CONCAT(N'CLAIM_REVIEW:',CONVERT(nvarchar(36),claim.ClaimId),N':',CASE WHEN link.ClaimId IS NULL THEN N'DOCUMENT' ELSE N'PATTERN' END)
  FROM Claims.Claim claim CROSS JOIN AI.IntelligenceCapability capability OUTER APPLY(SELECT TOP(1) documentLink.ClaimId FROM Claims.ClaimDocumentLink documentLink WHERE documentLink.TenantId=claim.TenantId AND documentLink.ClaimId=claim.ClaimId AND documentLink.IsDeleted=0) link WHERE capability.CapabilityCode=N'CLAIMS_INTELLIGENCE' AND capability.TenantId IS NULL AND capability.IsDeleted=0 AND claim.IsDeleted=0 AND claim.Status<>N'Closed' AND (link.ClaimId IS NULL OR claim.TotalIncurred>=@ClaimThreshold OR claim.IsLitigation=1 OR claim.IsDisputed=1 OR claim.IsCatastrophe=1)
  UNION ALL
  SELECT opportunity.TenantId,capability.IntelligenceCapabilityId,N'OPPORTUNITY',opportunity.OpportunityId,N'PRODUCER_FOLLOW_UP',SYSUTCDATETIME(),CASE WHEN opportunity.CloseDate<SYSUTCDATETIME() THEN N'HIGH' ELSE N'MEDIUM' END,CONVERT(decimal(18,6),opportunity.EstimatedAmount),CONVERT(decimal(5,4),1),N'Producer pipeline follow-up is due',CONCAT(opportunity.OpportunityName,N' has no recorded opportunity activity in the configured follow-up period.'),CONCAT(N'{"source":"CRM.Opportunity","stage":"',STRING_ESCAPE(opportunity.StageName,'json'),N'","forecastCategory":"',STRING_ESCAPE(opportunity.ForecastCategoryCode,'json'),N'","estimatedAmount":',opportunity.EstimatedAmount,N',"winProbability":',opportunity.WinProbability,N'}'),N'FOLLOW_UP_OPPORTUNITY',N'OPEN',opportunity.OwnerUserId,DATEADD(DAY,@DefaultDueDays,SYSUTCDATETIME()),CONCAT(N'PRODUCER_FOLLOWUP:',CONVERT(nvarchar(36),opportunity.OpportunityId))
  FROM CRM.Opportunity opportunity CROSS JOIN AI.IntelligenceCapability capability WHERE capability.CapabilityCode=N'PRODUCER_INTELLIGENCE' AND capability.TenantId IS NULL AND capability.IsDeleted=0 AND opportunity.IsDeleted=0 AND opportunity.StatusCodeId<>3 AND NOT EXISTS(SELECT 1 FROM CRM.OpportunityActivity activity WHERE activity.TenantId=opportunity.TenantId AND activity.OpportunityId=opportunity.OpportunityId AND activity.IsDeleted=0 AND activity.ActivityDate>=DATEADD(DAY,-@ProducerDays,SYSUTCDATETIME()))
  UNION ALL
  SELECT account.TenantId,capability.IntelligenceCapabilityId,N'ACCOUNT',account.AccountId,CASE WHEN policy.PolicyId IS NULL THEN N'CUSTOMER_COVERAGE_REVIEW' ELSE N'CUSTOMER_COMMUNICATION_GAP' END,SYSUTCDATETIME(),CASE WHEN policy.PolicyId IS NULL THEN N'HIGH' ELSE N'MEDIUM' END,CONVERT(decimal(18,6),COALESCE(account.AnnualRevenue,0)),CONVERT(decimal(5,4),1),CASE WHEN policy.PolicyId IS NULL THEN N'Customer coverage inventory requires review' ELSE N'Customer relationship follow-up is due' END,CASE WHEN policy.PolicyId IS NULL THEN N'No active bound policy is linked to this active customer account. Review coverage inventory and account status.' ELSE N'No recent account communication is recorded. Review relationship timeline, policy trends, and service needs.' END,CONCAT(N'{"source":"Client.Account","industry":"',STRING_ESCAPE(COALESCE(account.Industry,N''),'json'),N'","segment":"',STRING_ESCAPE(COALESCE(account.SegmentCode,N''),'json'),N'","annualRevenue":',COALESCE(account.AnnualRevenue,0),N',"activePolicyLinked":',CASE WHEN policy.PolicyId IS NULL THEN N'false' ELSE N'true' END,N'}'),CASE WHEN policy.PolicyId IS NULL THEN N'REVIEW_COVERAGE_INVENTORY' ELSE N'CONTACT_CUSTOMER' END,N'OPEN',account.OwnerUserId,DATEADD(DAY,@DefaultDueDays,SYSUTCDATETIME()),CONCAT(N'CUSTOMER_REVIEW:',CONVERT(nvarchar(36),account.AccountId),N':',CASE WHEN policy.PolicyId IS NULL THEN N'COVERAGE' ELSE N'COMMUNICATION' END)
  FROM Client.Account account CROSS JOIN AI.IntelligenceCapability capability OUTER APPLY(SELECT TOP(1) bound.PolicyId FROM Submissions.BoundPolicy bound WHERE bound.TenantId=account.TenantId AND bound.AccountId=account.AccountId AND bound.IsDeleted=0 AND bound.Status=N'Bound' AND bound.ExpirationDate>=SYSUTCDATETIME()) policy WHERE capability.CapabilityCode=N'CUSTOMER_INTELLIGENCE' AND capability.TenantId IS NULL AND capability.IsDeleted=0 AND account.IsDeleted=0 AND account.StatusCode=N'Active' AND (policy.PolicyId IS NULL OR NOT EXISTS(SELECT 1 FROM Client.AccountActivity activity WHERE activity.TenantId=account.TenantId AND activity.AccountId=account.AccountId AND activity.IsDeleted=0 AND activity.OccurredAtUtc>=DATEADD(DAY,-@CustomerGapDays,SYSUTCDATETIME())))
) source ON target.TenantId=source.TenantId AND target.IdempotencyKey=source.IdempotencyKey AND target.IsDeleted=0
WHEN MATCHED AND target.StatusCode IN(N'OPEN',N'REVIEW_REQUIRED',N'IN_PROGRESS') THEN UPDATE SET SeverityCode=source.SeverityCode,Score=source.Score,Confidence=source.Confidence,Title=source.Title,Summary=source.Summary,EvidenceJson=source.EvidenceJson,RecommendedActionCode=source.RecommendedActionCode,AssignedToUserId=source.AssignedToUserId,DueDateUtc=source.DueDateUtc,ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED BY SOURCE AND target.SignalTypeCode IN(N'FREQUENT_APPROVAL_POINT',N'RENEWAL_PRIORITY',N'CLAIM_MISSING_DOCUMENTATION',N'CLAIM_RULE_ASSISTED_REVIEW',N'PRODUCER_FOLLOW_UP',N'CUSTOMER_COVERAGE_REVIEW',N'CUSTOMER_COMMUNICATION_GAP') AND target.StatusCode IN(N'OPEN',N'REVIEW_REQUIRED',N'IN_PROGRESS') THEN UPDATE SET StatusCode=N'RESOLVED',ModifiedDateUtc=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(TenantId,IntelligenceCapabilityId,EntityTypeCode,EntityId,SignalTypeCode,SignalDateUtc,SeverityCode,Score,Confidence,Title,Summary,EvidenceJson,RecommendedActionCode,StatusCode,AssignedToUserId,DueDateUtc,IdempotencyKey,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.IntelligenceCapabilityId,source.EntityTypeCode,source.EntityId,source.SignalTypeCode,source.SignalDateUtc,source.SeverityCode,source.Score,source.Confidence,source.Title,source.Summary,source.EvidenceJson,source.RecommendedActionCode,source.StatusCode,source.AssignedToUserId,source.DueDateUtc,source.IdempotencyKey,SYSUTCDATETIME(),0);
SET @changed+=@@ROWCOUNT;
COMMIT TRANSACTION;
SELECT @changed;
""";
        return await ExecuteSynchronizationAsync(sql,"business intelligence",240,cancellationToken);
    }

    public async Task<int> ProcessPlatformWorkAsync(string leaseOwner,IntelligenceWorkerSettings settings,CancellationToken cancellationToken)
    {
        const string leaseSql="""DECLARE @leased TABLE(Id UNIQUEIDENTIFIER);;WITH candidates AS(SELECT TOP(@BatchSize)* FROM AI.IntelligenceWorkItem WITH(UPDLOCK,READPAST,ROWLOCK) WHERE IsDeleted=0 AND StatusCode IN(N'PENDING',N'RETRY') AND AvailableDateUtc<=SYSUTCDATETIME() AND (LeaseExpiresDateUtc IS NULL OR LeaseExpiresDateUtc<SYSUTCDATETIME()) ORDER BY Priority DESC,AvailableDateUtc,CreatedDateUtc) UPDATE candidates SET StatusCode=N'PROCESSING',LeaseOwner=@LeaseOwner,LeaseExpiresDateUtc=DATEADD(SECOND,@LeaseSeconds,SYSUTCDATETIME()),AttemptCount=AttemptCount+1,ModifiedDateUtc=SYSUTCDATETIME() OUTPUT inserted.IntelligenceWorkItemId INTO @leased;SELECT work.IntelligenceWorkItemId,work.TenantId,capability.CapabilityCode,work.WorkTypeCode,work.AttemptCount,work.MaximumAttempts FROM AI.IntelligenceWorkItem work JOIN @leased leased ON leased.Id=work.IntelligenceWorkItemId JOIN AI.IntelligenceCapability capability ON capability.IntelligenceCapabilityId=work.IntelligenceCapabilityId;""";
        using var connection=await connectionFactory.CreateOpenConnectionAsync(cancellationToken);
        var work=(await connection.QueryAsync<PlatformWork>(new CommandDefinition(leaseSql,new{LeaseOwner=leaseOwner,BatchSize=settings.PlatformBatchSize,LeaseSeconds=settings.PlatformLeaseSeconds},cancellationToken:cancellationToken))).AsList();
        foreach(var item in work)
        {
            try
            {
                if(item.WorkTypeCode is "SYNCHRONIZE_PROJECTIONS" or "EVALUATE_CONFIGURED_ENGINES")await SynchronizePlatformProjectionsAsync(cancellationToken);
                await connection.ExecuteAsync(new CommandDefinition("UPDATE AI.IntelligenceWorkItem SET StatusCode=N'COMPLETED',CompletedDateUtc=SYSUTCDATETIME(),LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,LastError=NULL,ModifiedDateUtc=SYSUTCDATETIME() WHERE IntelligenceWorkItemId=@Id AND TenantId=@TenantId AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';",new{Id=item.IntelligenceWorkItemId,item.TenantId,LeaseOwner=leaseOwner},cancellationToken:cancellationToken));
            }
            catch(Exception ex)
            {
                logger.LogError(ex,"Intelligence platform work {WorkItemId} failed.",item.IntelligenceWorkItemId);
                await connection.ExecuteAsync(new CommandDefinition("UPDATE AI.IntelligenceWorkItem SET StatusCode=CASE WHEN AttemptCount>=MaximumAttempts THEN N'FAILED' ELSE N'RETRY' END,AvailableDateUtc=DATEADD(MINUTE,POWER(2,CASE WHEN AttemptCount>8 THEN 8 ELSE AttemptCount END),SYSUTCDATETIME()),LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,LastError=@Error,ModifiedDateUtc=SYSUTCDATETIME() WHERE IntelligenceWorkItemId=@Id AND TenantId=@TenantId AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';",new{Id=item.IntelligenceWorkItemId,item.TenantId,LeaseOwner=leaseOwner,Error=Truncate(ex.Message,4000)},cancellationToken:cancellationToken));
            }
        }
        return work.Count;
    }

    public async Task<int> SynchronizeSearchIndexAsync(CancellationToken cancellationToken)
    {
        const string sql="""
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lockResult INT;
EXEC @lockResult=sys.sp_getapplock @Resource=N'AI.SearchPermission.Synchronize',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=0;
IF @lockResult<0 BEGIN ROLLBACK TRANSACTION; THROW 51000,'Intelligence search synchronization is already running.',1; END;
DECLARE @changed TABLE(SearchDocumentId UNIQUEIDENTIFIER);
MERGE AI.SearchDocument target USING(SELECT account.TenantId,N'ACCOUNT' EntityTypeCode,account.AccountId EntityId,N'Accounts' ModuleCode,account.AccountName Title,CONCAT_WS(N' ',account.AccountNumber,account.AccountName,account.AccountTypeCode,account.StatusCode,account.SegmentCode,account.LifecycleStageCode,account.Industry,account.MainEmail,account.MainPhone) ContentText,CONCAT_WS(N' ',account.Industry,account.SegmentCode,account.AccountTypeCode) Keywords,account.OwnerUserId PrincipalUserId,CONVERT(char(64),HASHBYTES('SHA2_256',CONCAT_WS(N'|',account.AccountNumber,account.AccountName,account.StatusCode,account.SegmentCode,account.Industry,account.ModifiedDateUtc)),2) ContentHash,COALESCE(account.ModifiedDateUtc,account.CreatedDateUtc) SourceModifiedDateUtc,account.CreatedDateUtc SourceCreatedDateUtc FROM Client.Account account WHERE account.IsDeleted=0) source ON target.TenantId=source.TenantId AND target.EntityTypeCode=source.EntityTypeCode AND target.EntityId=source.EntityId WHEN MATCHED AND (target.ContentHash<>source.ContentHash OR target.IsDeleted=1 OR target.SourceCreatedDateUtc IS NULL) THEN UPDATE SET ModuleCode=source.ModuleCode,Title=source.Title,ContentText=source.ContentText,Keywords=source.Keywords,ContentHash=source.ContentHash,IndexedDateUtc=SYSUTCDATETIME(),SourceModifiedDateUtc=source.SourceModifiedDateUtc,SourceCreatedDateUtc=source.SourceCreatedDateUtc,ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0 WHEN NOT MATCHED THEN INSERT(TenantId,EntityTypeCode,EntityId,ModuleCode,Title,ContentText,Keywords,SecurityScopeJson,ContentHash,IndexedDateUtc,SourceModifiedDateUtc,SourceCreatedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.EntityTypeCode,source.EntityId,source.ModuleCode,source.Title,source.ContentText,source.Keywords,N'{}',source.ContentHash,SYSUTCDATETIME(),source.SourceModifiedDateUtc,source.SourceCreatedDateUtc,SYSUTCDATETIME(),0) OUTPUT inserted.SearchDocumentId INTO @changed;
MERGE AI.SearchDocument target USING(SELECT submission.TenantId,N'SUBMISSION' EntityTypeCode,submission.SubmissionId EntityId,N'Submissions' ModuleCode,CONCAT(submission.SubmissionNumber,N' · ',account.AccountName) Title,CONCAT_WS(N' ',submission.SubmissionNumber,account.AccountName,submission.LineOfBusiness,submission.Status,submission.Priority) ContentText,CONCAT_WS(N' ',submission.LineOfBusiness,submission.Status,submission.Priority) Keywords,submission.AssignedToUserId PrincipalUserId,CONVERT(char(64),HASHBYTES('SHA2_256',CONCAT_WS(N'|',submission.SubmissionNumber,account.AccountName,submission.LineOfBusiness,submission.Status,submission.Priority,submission.ModifiedDateUtc)),2) ContentHash,COALESCE(submission.ModifiedDateUtc,submission.CreatedDateUtc) SourceModifiedDateUtc,submission.CreatedDateUtc SourceCreatedDateUtc FROM Submissions.Submission submission JOIN Client.Account account ON account.TenantId=submission.TenantId AND account.AccountId=submission.AccountId AND account.IsDeleted=0 WHERE submission.IsDeleted=0) source ON target.TenantId=source.TenantId AND target.EntityTypeCode=source.EntityTypeCode AND target.EntityId=source.EntityId WHEN MATCHED AND (target.ContentHash<>source.ContentHash OR target.IsDeleted=1 OR target.SourceCreatedDateUtc IS NULL) THEN UPDATE SET ModuleCode=source.ModuleCode,Title=source.Title,ContentText=source.ContentText,Keywords=source.Keywords,ContentHash=source.ContentHash,IndexedDateUtc=SYSUTCDATETIME(),SourceModifiedDateUtc=source.SourceModifiedDateUtc,SourceCreatedDateUtc=source.SourceCreatedDateUtc,ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0 WHEN NOT MATCHED THEN INSERT(TenantId,EntityTypeCode,EntityId,ModuleCode,Title,ContentText,Keywords,SecurityScopeJson,ContentHash,IndexedDateUtc,SourceModifiedDateUtc,SourceCreatedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.EntityTypeCode,source.EntityId,source.ModuleCode,source.Title,source.ContentText,source.Keywords,N'{}',source.ContentHash,SYSUTCDATETIME(),source.SourceModifiedDateUtc,source.SourceCreatedDateUtc,SYSUTCDATETIME(),0) OUTPUT inserted.SearchDocumentId INTO @changed;
MERGE AI.SearchDocument target USING(SELECT claim.TenantId,N'CLAIM' EntityTypeCode,claim.ClaimId EntityId,N'Claims' ModuleCode,CONCAT(claim.ClaimNumber,N' · ',claim.AccountName) Title,CONCAT_WS(N' ',claim.ClaimNumber,claim.PolicyNumber,claim.AccountName,claim.Lob,claim.Carrier,claim.Status,claim.LossType,claim.PrimaryClaimant,claim.LossDescription,claim.CauseOfLoss,claim.LossLocation,claim.StateOfLoss) ContentText,CONCAT_WS(N' ',claim.Lob,claim.Status,claim.LossType,claim.CauseOfLoss) Keywords,CAST(NULL AS UNIQUEIDENTIFIER) PrincipalUserId,CONVERT(char(64),HASHBYTES('SHA2_256',CONCAT_WS(N'|',claim.ClaimNumber,claim.Status,claim.TotalIncurred,claim.LossDescription,claim.ModifiedDateUtc)),2) ContentHash,COALESCE(claim.ModifiedDateUtc,claim.CreatedDateUtc) SourceModifiedDateUtc,claim.CreatedDateUtc SourceCreatedDateUtc FROM Claims.Claim claim WHERE claim.IsDeleted=0) source ON target.TenantId=source.TenantId AND target.EntityTypeCode=source.EntityTypeCode AND target.EntityId=source.EntityId WHEN MATCHED AND (target.ContentHash<>source.ContentHash OR target.IsDeleted=1 OR target.SourceCreatedDateUtc IS NULL) THEN UPDATE SET ModuleCode=source.ModuleCode,Title=source.Title,ContentText=source.ContentText,Keywords=source.Keywords,ContentHash=source.ContentHash,IndexedDateUtc=SYSUTCDATETIME(),SourceModifiedDateUtc=source.SourceModifiedDateUtc,SourceCreatedDateUtc=source.SourceCreatedDateUtc,ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0 WHEN NOT MATCHED THEN INSERT(TenantId,EntityTypeCode,EntityId,ModuleCode,Title,ContentText,Keywords,SecurityScopeJson,ContentHash,IndexedDateUtc,SourceModifiedDateUtc,SourceCreatedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.EntityTypeCode,source.EntityId,source.ModuleCode,source.Title,source.ContentText,source.Keywords,N'{}',source.ContentHash,SYSUTCDATETIME(),source.SourceModifiedDateUtc,source.SourceCreatedDateUtc,SYSUTCDATETIME(),0) OUTPUT inserted.SearchDocumentId INTO @changed;
MERGE AI.SearchDocument target USING(SELECT document.TenantId,N'DOCUMENT' EntityTypeCode,document.DocumentId EntityId,N'Documents' ModuleCode,document.FileName Title,CONCAT_WS(N' ',document.FileName,document.DocumentTypeCode,document.CategoryCode,document.EntityName,document.Description,document.Tags,document.StatusCode) ContentText,CONCAT_WS(N' ',document.DocumentTypeCode,document.CategoryCode,document.Tags) Keywords,document.CreatedByUserId PrincipalUserId,CONVERT(char(64),HASHBYTES('SHA2_256',CONCAT_WS(N'|',document.FileName,document.DocumentTypeCode,document.Description,document.Tags,document.ModifiedDateUtc)),2) ContentHash,COALESCE(document.ModifiedDateUtc,document.CreatedDateUtc) SourceModifiedDateUtc,document.CreatedDateUtc SourceCreatedDateUtc FROM DMS.Document document WHERE document.IsDeleted=0) source ON target.TenantId=source.TenantId AND target.EntityTypeCode=source.EntityTypeCode AND target.EntityId=source.EntityId WHEN MATCHED AND (target.ContentHash<>source.ContentHash OR target.IsDeleted=1 OR target.SourceCreatedDateUtc IS NULL) THEN UPDATE SET ModuleCode=source.ModuleCode,Title=source.Title,ContentText=source.ContentText,Keywords=source.Keywords,ContentHash=source.ContentHash,IndexedDateUtc=SYSUTCDATETIME(),SourceModifiedDateUtc=source.SourceModifiedDateUtc,SourceCreatedDateUtc=source.SourceCreatedDateUtc,ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0 WHEN NOT MATCHED THEN INSERT(TenantId,EntityTypeCode,EntityId,ModuleCode,Title,ContentText,Keywords,SecurityScopeJson,ContentHash,IndexedDateUtc,SourceModifiedDateUtc,SourceCreatedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.EntityTypeCode,source.EntityId,source.ModuleCode,source.Title,source.ContentText,source.Keywords,N'{}',source.ContentHash,SYSUTCDATETIME(),source.SourceModifiedDateUtc,source.SourceCreatedDateUtc,SYSUTCDATETIME(),0) OUTPUT inserted.SearchDocumentId INTO @changed;
UPDATE document SET IsDeleted=1,ModifiedDateUtc=SYSUTCDATETIME() FROM AI.SearchDocument document WHERE document.IsDeleted=0 AND ((document.EntityTypeCode=N'ACCOUNT' AND NOT EXISTS(SELECT 1 FROM Client.Account source WHERE source.TenantId=document.TenantId AND source.AccountId=document.EntityId AND source.IsDeleted=0)) OR (document.EntityTypeCode=N'SUBMISSION' AND NOT EXISTS(SELECT 1 FROM Submissions.Submission source WHERE source.TenantId=document.TenantId AND source.SubmissionId=document.EntityId AND source.IsDeleted=0)) OR (document.EntityTypeCode=N'CLAIM' AND NOT EXISTS(SELECT 1 FROM Claims.Claim source WHERE source.TenantId=document.TenantId AND source.ClaimId=document.EntityId AND source.IsDeleted=0)) OR (document.EntityTypeCode=N'DOCUMENT' AND NOT EXISTS(SELECT 1 FROM DMS.Document source WHERE source.TenantId=document.TenantId AND source.DocumentId=document.EntityId AND source.IsDeleted=0)));
DELETE FROM AI.SearchPermission;
INSERT AI.SearchPermission(TenantId,SearchDocumentId,PrincipalTypeCode,PrincipalId,PermissionCode,CreatedDateUtc,IsDeleted) SELECT DISTINCT document.TenantId,document.SearchDocumentId,N'ROLE',rolePermission.RoleId,N'READ',SYSUTCDATETIME(),0 FROM AI.SearchDocument document JOIN IAM.Permission permission ON permission.PermissionCode=CASE document.ModuleCode WHEN N'Accounts' THEN N'ACCOUNT_VIEW' WHEN N'Submissions' THEN N'SUBMISSION_VIEW' WHEN N'Claims' THEN N'CLAIM_VIEW' WHEN N'Documents' THEN N'DOCUMENT_VIEW' END OR permission.PermissionCode=N'NAV_ALL' JOIN IAM.RolePermission rolePermission ON rolePermission.PermissionId=permission.PermissionId AND rolePermission.IsDeleted=0 JOIN IAM.Role role ON role.RoleId=rolePermission.RoleId AND role.TenantId=document.TenantId AND role.IsDeleted=0 WHERE document.IsDeleted=0 AND permission.IsDeleted=0;
INSERT AI.SearchPermission(TenantId,SearchDocumentId,PrincipalTypeCode,PrincipalId,PermissionCode,CreatedDateUtc,IsDeleted) SELECT document.TenantId,document.SearchDocumentId,N'USER',source.PrincipalUserId,N'READ',SYSUTCDATETIME(),0 FROM AI.SearchDocument document CROSS APPLY(SELECT CASE document.EntityTypeCode WHEN N'ACCOUNT' THEN (SELECT OwnerUserId FROM Client.Account WHERE TenantId=document.TenantId AND AccountId=document.EntityId) WHEN N'SUBMISSION' THEN (SELECT AssignedToUserId FROM Submissions.Submission WHERE TenantId=document.TenantId AND SubmissionId=document.EntityId) WHEN N'DOCUMENT' THEN (SELECT CreatedByUserId FROM DMS.Document WHERE TenantId=document.TenantId AND DocumentId=document.EntityId) END PrincipalUserId) source WHERE document.IsDeleted=0 AND source.PrincipalUserId IS NOT NULL;
DECLARE @changedCount INT=(SELECT COUNT(1) FROM @changed);
COMMIT TRANSACTION;
SELECT @changedCount;
""";
        return await ExecuteSynchronizationAsync(sql,"search index",180,cancellationToken);
    }

    private async Task<int> ExecuteSynchronizationAsync(string sql,string synchronizationName,int commandTimeout,CancellationToken cancellationToken)
    {
        try
        {
            using var connection=await connectionFactory.CreateOpenConnectionAsync(cancellationToken);
            return await connection.ExecuteScalarAsync<int>(new CommandDefinition(sql,commandTimeout:commandTimeout,cancellationToken:cancellationToken));
        }
        catch(SqlException ex)when(IsSynchronizationAlreadyRunning(ex))
        {
            logger.LogDebug("Skipped {SynchronizationName} synchronization because another worker owns the synchronization lock.",synchronizationName);
            return 0;
        }
    }

    private static bool IsSynchronizationAlreadyRunning(SqlException exception)
        => exception.Number==51000
           && exception.Message.Contains("synchronization is already running.",StringComparison.OrdinalIgnoreCase);

    public async Task<int> ProcessRecommendationsAsync(string leaseOwner,IntelligenceWorkerSettings settings,CancellationToken cancellationToken)
    {
        const string leaseSql="""DECLARE @leased TABLE(Id UNIQUEIDENTIFIER);;WITH candidates AS(SELECT TOP(@BatchSize)* FROM AI.RecommendationWorkItem WITH(UPDLOCK,READPAST,ROWLOCK) WHERE IsDeleted=0 AND StatusCode IN(N'PENDING',N'RETRY') AND AvailableDateUtc<=SYSUTCDATETIME() AND (LeaseExpiresDateUtc IS NULL OR LeaseExpiresDateUtc<SYSUTCDATETIME()) ORDER BY AvailableDateUtc,CreatedDateUtc) UPDATE candidates SET StatusCode=N'PROCESSING',LeaseOwner=@LeaseOwner,LeaseExpiresDateUtc=DATEADD(SECOND,@LeaseSeconds,SYSUTCDATETIME()),AttemptCount=AttemptCount+1,ModifiedDateUtc=SYSUTCDATETIME() OUTPUT inserted.RecommendationWorkItemId INTO @leased;SELECT work.RecommendationWorkItemId,work.TenantId,work.EntityTypeCode,work.EntityId,work.CorrelationId,work.AttemptCount,work.MaximumAttempts FROM AI.RecommendationWorkItem work JOIN @leased leased ON leased.Id=work.RecommendationWorkItemId;""";
        using var connection=await connectionFactory.CreateOpenConnectionAsync(cancellationToken);var work=(await connection.QueryAsync<RecommendationWork>(new CommandDefinition(leaseSql,new{LeaseOwner=leaseOwner,settings.BatchSize,LeaseSeconds=settings.LeaseSeconds},cancellationToken:cancellationToken))).AsList();
        foreach(var item in work){try{await GenerateRecommendationsAsync(connection,item,leaseOwner,cancellationToken);}catch(Exception ex){logger.LogError(ex,"Recommendation work {WorkItemId} failed.",item.RecommendationWorkItemId);await FailRecommendationAsync(connection,item,leaseOwner,ex,cancellationToken);}}
        return work.Count;
    }

    public async Task<int> ProcessEvaluationsAsync(string leaseOwner,IntelligenceWorkerSettings settings,CancellationToken cancellationToken)
    {
        const string leaseSql="""DECLARE @leased TABLE(Id UNIQUEIDENTIFIER);;WITH candidates AS(SELECT TOP(20)* FROM AI.EvaluationRun WITH(UPDLOCK,READPAST,ROWLOCK) WHERE IsDeleted=0 AND (StatusCode=N'QUEUED' OR (StatusCode=N'PROCESSING' AND LeaseExpiresDateUtc<SYSUTCDATETIME())) ORDER BY CreatedDateUtc) UPDATE candidates SET StatusCode=N'PROCESSING',StartedDateUtc=SYSUTCDATETIME(),LeaseOwner=@LeaseOwner,LeaseExpiresDateUtc=DATEADD(SECOND,@LeaseSeconds,SYSUTCDATETIME()),ModifiedDateUtc=SYSUTCDATETIME() OUTPUT inserted.EvaluationRunId INTO @leased;SELECT run.EvaluationRunId,run.TenantId,run.WindowStartUtc,run.WindowEndUtc,definition.MetricCode,definition.CalculationCode,definition.TargetValue,definition.WarningValue,definition.MinimumSampleSize,definition.ConfigurationJson FROM AI.EvaluationRun run JOIN @leased leased ON leased.Id=run.EvaluationRunId JOIN AI.EvaluationDefinition definition ON definition.EvaluationDefinitionId=run.EvaluationDefinitionId;""";using var connection=await connectionFactory.CreateOpenConnectionAsync(cancellationToken);var runs=(await connection.QueryAsync<EvaluationWork>(new CommandDefinition(leaseSql,new{LeaseOwner=leaseOwner,LeaseSeconds=settings.LeaseSeconds},cancellationToken:cancellationToken))).AsList();foreach(var run in runs){try{await CompleteEvaluationAsync(connection,run,leaseOwner,cancellationToken);}catch(Exception ex){logger.LogError(ex,"Evaluation run {EvaluationRunId} failed.",run.EvaluationRunId);await connection.ExecuteAsync(new CommandDefinition("UPDATE AI.EvaluationRun SET StatusCode=N'FAILED',ErrorMessage=@Error,CompletedDateUtc=SYSUTCDATETIME(),LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,ModifiedDateUtc=SYSUTCDATETIME() WHERE EvaluationRunId=@Id AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';",new{Id=run.EvaluationRunId,LeaseOwner=leaseOwner,Error=Truncate(ex.Message,4000)},cancellationToken:cancellationToken));}}return runs.Count;
    }

    private static async Task GenerateRecommendationsAsync(IDbConnection connection,RecommendationWork item,string leaseOwner,CancellationToken cancellationToken)
    {
        const string ruleSql="""SELECT rule.RecommendationRuleId,platformRule.ConditionJson FROM AI.RecommendationRule rule JOIN AI.RecommendationType type ON type.RecommendationTypeId=rule.RecommendationTypeId AND type.IsActive=1 AND type.IsDeleted=0 JOIN Rules.RuleDefinition platformRule ON platformRule.TenantId=rule.TenantId AND platformRule.RuleCode=CONCAT(N'RECOMMENDATION.',rule.RuleCode) AND platformRule.VersionNumber=1 AND platformRule.IsActive=1 AND platformRule.IsDeleted=0 WHERE rule.TenantId=@TenantId AND rule.EntityTypeCode=@EntityTypeCode AND rule.IsActive=1 AND rule.IsDeleted=0 AND rule.EffectiveFromUtc<=SYSUTCDATETIME() AND (rule.EffectiveToUtc IS NULL OR rule.EffectiveToUtc>SYSUTCDATETIME());SELECT CASE @EntityTypeCode WHEN N'ACCOUNT' THEN (SELECT AccountName accountName,AccountTypeCode accountTypeCode,StatusCode statusCode,SegmentCode segmentCode,Industry industry,AnnualRevenue annualRevenue FROM Client.Account WHERE TenantId=@TenantId AND AccountId=@EntityId AND IsDeleted=0 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) WHEN N'SUBMISSION' THEN (SELECT LineOfBusiness lineOfBusiness,Status status,Priority priority,TargetPremium targetPremium,EffectiveDate effectiveDate FROM Submissions.Submission WHERE TenantId=@TenantId AND SubmissionId=@EntityId AND IsDeleted=0 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) WHEN N'CLAIM' THEN (SELECT Status status,Lob lineOfBusiness,LossType lossType,TotalIncurred totalIncurred,IsLitigation isLitigation,IsDisputed isDisputed,IsCatastrophe isCatastrophe FROM Claims.Claim WHERE TenantId=@TenantId AND ClaimId=@EntityId AND IsDeleted=0 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) WHEN N'OPPORTUNITY' THEN (SELECT OpportunityName opportunityName,StageName stageName,ForecastCategoryCode forecastCategoryCode,EstimatedAmount estimatedAmount,WinProbability winProbability,CloseDate closeDate FROM CRM.Opportunity WHERE TenantId=@TenantId AND OpportunityId=@EntityId AND IsDeleted=0 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) END;SELECT TOP(1) COALESCE(SettingValue,DefaultValue) FROM Core.ConfigurationSetting WHERE SettingKey IN(N'Platform.Rules.AllowedConditionOperators',N'Intelligence.Recommendation.AllowedConditionOperators') AND IsDeleted=0 AND (TenantId=@TenantId OR TenantId IS NULL) ORDER BY CASE WHEN TenantId=@TenantId THEN 0 ELSE 1 END,CASE WHEN SettingKey=N'Platform.Rules.AllowedConditionOperators' THEN 0 ELSE 1 END;""";
        using var multi=await connection.QueryMultipleAsync(new CommandDefinition(ruleSql,item,cancellationToken:cancellationToken));var rules=(await multi.ReadAsync<RecommendationRuleCondition>()).AsList();var snapshotJson=await multi.ReadSingleOrDefaultAsync<string>();var allowedOperatorsJson=await multi.ReadSingleOrDefaultAsync<string>();JsonElement? snapshot=string.IsNullOrWhiteSpace(snapshotJson)?null:JsonDocument.Parse(snapshotJson).RootElement.Clone();var allowedOperators=ParseAllowedOperators(allowedOperatorsJson);var matched=rules.Where(rule=>snapshot.HasValue&&EvaluateCondition(rule.ConditionJson,snapshot.Value,allowedOperators)).Select(rule=>rule.RecommendationRuleId).ToArray();
        const string sql="""INSERT AI.Recommendation(TenantId,RecommendationTypeId,RecommendationRuleId,EntityTypeCode,EntityId,Title,Summary,Rationale,ActionCode,ActionPayloadJson,PriorityCode,StatusCode,Confidence,Score,ExpiresDateUtc,IdempotencyKey,CreatedDateUtc,CreatedByUserId,IsDeleted) SELECT @TenantId,type.RecommendationTypeId,rule.RecommendationRuleId,@EntityTypeCode,@EntityId,COALESCE(NULLIF(JSON_VALUE(rule.ActionJson,'$.title'),N''),rule.Name),COALESCE(NULLIF(JSON_VALUE(rule.ActionJson,'$.summary'),N''),rule.Description,rule.Name),JSON_VALUE(rule.ActionJson,'$.rationale'),JSON_VALUE(rule.ActionJson,'$.actionCode'),JSON_QUERY(rule.ActionJson,'$.payload'),type.DefaultPriorityCode,CASE WHEN type.RequiresHumanReview=1 THEN N'REVIEW_REQUIRED' ELSE N'OPEN' END,rule.MinimumConfidence,CONVERT(decimal(18,6),rule.Priority),CASE WHEN type.DefaultExpirationHours IS NULL THEN NULL ELSE DATEADD(HOUR,type.DefaultExpirationHours,SYSUTCDATETIME()) END,CONCAT(CONVERT(nvarchar(36),@WorkItemId),N':',CONVERT(nvarchar(36),rule.RecommendationRuleId)),SYSUTCDATETIME(),@CreatedByUserId,0 FROM AI.RecommendationRule rule JOIN AI.RecommendationType type ON type.RecommendationTypeId=rule.RecommendationTypeId AND type.IsActive=1 AND type.IsDeleted=0 WHERE rule.RecommendationRuleId IN @MatchedRuleIds AND NOT EXISTS(SELECT 1 FROM AI.Recommendation existing WHERE existing.TenantId=@TenantId AND existing.IdempotencyKey=CONCAT(CONVERT(nvarchar(36),@WorkItemId),N':',CONVERT(nvarchar(36),rule.RecommendationRuleId)) AND existing.IsDeleted=0);INSERT AI.RecommendationEvidence(TenantId,RecommendationId,EvidenceTypeCode,SourceEntityTypeCode,SourceEntityId,Description,RelevanceScore,CreatedDateUtc,CreatedByUserId,IsDeleted) SELECT recommendation.TenantId,recommendation.RecommendationId,N'GOVERNED_RULE',N'RECOMMENDATION_RULE',recommendation.RecommendationRuleId,N'Generated after evaluating an active tenant-governed recommendation condition against an authoritative entity snapshot.',recommendation.Confidence,SYSUTCDATETIME(),@CreatedByUserId,0 FROM AI.Recommendation recommendation WHERE recommendation.TenantId=@TenantId AND recommendation.IdempotencyKey LIKE CONCAT(CONVERT(nvarchar(36),@WorkItemId),N':%') AND NOT EXISTS(SELECT 1 FROM AI.RecommendationEvidence evidence WHERE evidence.RecommendationId=recommendation.RecommendationId AND evidence.EvidenceTypeCode=N'GOVERNED_RULE' AND evidence.IsDeleted=0);INSERT AI.ReviewQueueItem(TenantId,ReviewTypeCode,SourceEntityTypeCode,SourceEntityId,Title,Summary,PriorityCode,StatusCode,Confidence,IdempotencyKey,CreatedDateUtc,CreatedByUserId,IsDeleted) SELECT recommendation.TenantId,N'RECOMMENDATION',N'RECOMMENDATION',recommendation.RecommendationId,recommendation.Title,recommendation.Summary,recommendation.PriorityCode,N'OPEN',recommendation.Confidence,CONCAT(N'RECOMMENDATION:',CONVERT(nvarchar(36),recommendation.RecommendationId)),SYSUTCDATETIME(),@CreatedByUserId,0 FROM AI.Recommendation recommendation WHERE recommendation.TenantId=@TenantId AND recommendation.IdempotencyKey LIKE CONCAT(CONVERT(nvarchar(36),@WorkItemId),N':%') AND recommendation.StatusCode=N'REVIEW_REQUIRED' AND NOT EXISTS(SELECT 1 FROM AI.ReviewQueueItem review WHERE review.TenantId=recommendation.TenantId AND review.IdempotencyKey=CONCAT(N'RECOMMENDATION:',CONVERT(nvarchar(36),recommendation.RecommendationId)) AND review.IsDeleted=0);UPDATE AI.RecommendationWorkItem SET StatusCode=N'COMPLETED',LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,ModifiedDateUtc=SYSUTCDATETIME() WHERE RecommendationWorkItemId=@WorkItemId AND TenantId=@TenantId AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';""";await connection.ExecuteAsync(new CommandDefinition(sql,new{item.TenantId,item.EntityTypeCode,item.EntityId,WorkItemId=item.RecommendationWorkItemId,CreatedByUserId=(Guid?)null,LeaseOwner=leaseOwner,MatchedRuleIds=matched.Length==0?[Guid.Empty]:matched},cancellationToken:cancellationToken));
    }

    private static bool EvaluateCondition(string json,JsonElement snapshot,IReadOnlySet<string> allowedOperators)
    {
        try
        {
            using var document=JsonDocument.Parse(json);var root=document.RootElement;if(root.ValueKind!=JsonValueKind.Object)return false;if(root.TryGetProperty("all",out var all)&&all.ValueKind==JsonValueKind.Array)return all.GetArrayLength()>0&&all.EnumerateArray().All(condition=>EvaluateCondition(condition.GetRawText(),snapshot,allowedOperators));if(root.TryGetProperty("any",out var any)&&any.ValueKind==JsonValueKind.Array)return any.EnumerateArray().Any(condition=>EvaluateCondition(condition.GetRawText(),snapshot,allowedOperators));if(!root.TryGetProperty("field",out var fieldElement)||!root.TryGetProperty("operator",out var operatorElement))return false;var field=fieldElement.GetString();var operation=operatorElement.GetString()?.ToUpperInvariant();if(string.IsNullOrWhiteSpace(field)||string.IsNullOrWhiteSpace(operation)||!allowedOperators.Contains(operation))return false;if(!snapshot.TryGetProperty(field,out var actual))return operation=="IS_EMPTY";root.TryGetProperty("value",out var expected);var actualText=actual.ValueKind==JsonValueKind.String?actual.GetString():actual.GetRawText();var expectedText=expected.ValueKind==JsonValueKind.String?expected.GetString():expected.GetRawText();return operation switch{"EQUALS"=>string.Equals(actualText,expectedText,StringComparison.OrdinalIgnoreCase),"NOT_EQUALS"=>!string.Equals(actualText,expectedText,StringComparison.OrdinalIgnoreCase),"IS_EMPTY"=>string.IsNullOrWhiteSpace(actualText)||actual.ValueKind is JsonValueKind.Null or JsonValueKind.Undefined,"IS_NOT_EMPTY"=>!string.IsNullOrWhiteSpace(actualText)&&actual.ValueKind is not(JsonValueKind.Null or JsonValueKind.Undefined),"CONTAINS"=>actualText?.Contains(expectedText??string.Empty,StringComparison.OrdinalIgnoreCase)==true,"IN"=>expected.ValueKind==JsonValueKind.Array&&expected.EnumerateArray().Any(value=>string.Equals(actualText,value.ToString(),StringComparison.OrdinalIgnoreCase)),"GREATER_THAN"=>TryCompareNumbers(actualText,expectedText,out var greater)&&greater>0,"GREATER_THAN_OR_EQUAL"=>TryCompareNumbers(actualText,expectedText,out var greaterOrEqual)&&greaterOrEqual>=0,"LESS_THAN"=>TryCompareNumbers(actualText,expectedText,out var less)&&less<0,"LESS_THAN_OR_EQUAL"=>TryCompareNumbers(actualText,expectedText,out var lessOrEqual)&&lessOrEqual<=0,_=>false};
        }
        catch(JsonException){return false;}
    }

    private static IReadOnlySet<string> ParseAllowedOperators(string? json)
    {
        if(string.IsNullOrWhiteSpace(json))return new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        try{using var document=JsonDocument.Parse(json);return document.RootElement.ValueKind==JsonValueKind.Array?document.RootElement.EnumerateArray().Select(x=>x.GetString()).Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>x!.ToUpperInvariant()).ToHashSet(StringComparer.OrdinalIgnoreCase):new HashSet<string>(StringComparer.OrdinalIgnoreCase);}
        catch(JsonException){return new HashSet<string>(StringComparer.OrdinalIgnoreCase);}
    }

    private static bool TryCompareNumbers(string? left,string? right,out int comparison)
    {
        if(decimal.TryParse(left,System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.InvariantCulture,out var leftValue)&&decimal.TryParse(right,System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.InvariantCulture,out var rightValue)){comparison=leftValue.CompareTo(rightValue);return true;}
        comparison=0;return false;
    }

    private static Task FailRecommendationAsync(IDbConnection connection,RecommendationWork item,string leaseOwner,Exception exception,CancellationToken cancellationToken)=>connection.ExecuteAsync(new CommandDefinition("UPDATE AI.RecommendationWorkItem SET StatusCode=CASE WHEN AttemptCount>=MaximumAttempts THEN N'DEAD_LETTER' ELSE N'RETRY' END,AvailableDateUtc=DATEADD(SECOND,POWER(2,CASE WHEN AttemptCount>8 THEN 8 ELSE AttemptCount END)*15,SYSUTCDATETIME()),LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,LastErrorMessage=@Error,ModifiedDateUtc=SYSUTCDATETIME() WHERE RecommendationWorkItemId=@Id AND TenantId=@TenantId AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';",new{Id=item.RecommendationWorkItemId,item.TenantId,LeaseOwner=leaseOwner,Error=Truncate(exception.Message,4000)},cancellationToken:cancellationToken));

    private static async Task CompleteEvaluationAsync(IDbConnection connection,EvaluationWork work,string leaseOwner,CancellationToken cancellationToken)
    {
        var (count,value)=work.CalculationCode.ToUpperInvariant() switch
        {
            "SUCCESS_RATE"=>await ScalarAsync(connection,work,"SELECT COUNT(1) Count,AVG(CONVERT(decimal(18,6),CASE WHEN StatusCode=N'COMPLETED' THEN 1.0 ELSE 0 END)) Value FROM AI.Execution WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND StartedDateUtc>=@Start AND StartedDateUtc<@End",cancellationToken),
            "AVERAGE_CONFIDENCE"=>await ScalarAsync(connection,work,"SELECT COUNT(Confidence) Count,AVG(CONVERT(decimal(18,6),Confidence)) Value FROM AI.Execution WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND StartedDateUtc>=@Start AND StartedDateUtc<@End",cancellationToken),
            "AVERAGE_DURATION_MS"=>await ScalarAsync(connection,work,"SELECT COUNT(DurationMilliseconds) Count,AVG(CONVERT(decimal(18,6),DurationMilliseconds)) Value FROM AI.Execution WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND StartedDateUtc>=@Start AND StartedDateUtc<@End",cancellationToken),
            "CORRECTION_RATE"=>await ScalarAsync(connection,work,"SELECT COUNT(1) Count,AVG(CONVERT(decimal(18,6),CASE WHEN feedback.CorrectionReference IS NOT NULL THEN 1.0 ELSE 0 END)) Value FROM AI.ExecutionFeedback feedback JOIN AI.Execution execution ON execution.ExecutionId=feedback.ExecutionId WHERE (feedback.TenantId=@TenantId OR @TenantId IS NULL) AND feedback.IsDeleted=0 AND execution.StartedDateUtc>=@Start AND execution.StartedDateUtc<@End",cancellationToken),
            "LABELED_ACCURACY"=>await ScalarAsync(connection,work,"SELECT COUNT(1) Count,AVG(CONVERT(decimal(18,6),CASE WHEN IsAccurate=1 THEN 1.0 ELSE 0 END)) Value FROM AI.EvaluationSampleLabel WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND LabeledDateUtc>=@Start AND LabeledDateUtc<@End",cancellationToken),
            "LABELED_PRECISION"=>await ScalarAsync(connection,work,"SELECT COUNT(1) Count,CASE WHEN SUM(CASE WHEN PredictedPositive=1 THEN 1 ELSE 0 END)=0 THEN NULL ELSE CONVERT(decimal(18,6),SUM(CASE WHEN PredictedPositive=1 AND ActualPositive=1 THEN 1.0 ELSE 0 END)/SUM(CASE WHEN PredictedPositive=1 THEN 1.0 ELSE 0 END)) END Value FROM AI.EvaluationSampleLabel WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND LabeledDateUtc>=@Start AND LabeledDateUtc<@End",cancellationToken),
            "LABELED_RECALL"=>await ScalarAsync(connection,work,"SELECT COUNT(1) Count,CASE WHEN SUM(CASE WHEN ActualPositive=1 THEN 1 ELSE 0 END)=0 THEN NULL ELSE CONVERT(decimal(18,6),SUM(CASE WHEN PredictedPositive=1 AND ActualPositive=1 THEN 1.0 ELSE 0 END)/SUM(CASE WHEN ActualPositive=1 THEN 1.0 ELSE 0 END)) END Value FROM AI.EvaluationSampleLabel WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND LabeledDateUtc>=@Start AND LabeledDateUtc<@End",cancellationToken),
            "HALLUCINATION_RATE"=>await ScalarAsync(connection,work,"SELECT COUNT(1) Count,AVG(CONVERT(decimal(18,6),CASE WHEN IsHallucination=1 THEN 1.0 ELSE 0 END)) Value FROM AI.EvaluationSampleLabel WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND LabeledDateUtc>=@Start AND LabeledDateUtc<@End",cancellationToken),
            "SAFETY_EVENT_RATE"=>await ScalarAsync(connection,work,"SELECT COUNT(execution.ExecutionId) Count,CASE WHEN COUNT(execution.ExecutionId)=0 THEN NULL ELSE CONVERT(decimal(18,6),COUNT(DISTINCT safety.SafetyEventId)*1.0/COUNT(DISTINCT execution.ExecutionId)) END Value FROM AI.Execution execution LEFT JOIN AI.SafetyEvent safety ON safety.ExecutionId=execution.ExecutionId AND safety.IsDeleted=0 WHERE (execution.TenantId=@TenantId OR @TenantId IS NULL) AND execution.IsDeleted=0 AND execution.StartedDateUtc>=@Start AND execution.StartedDateUtc<@End",cancellationToken),
            _=>throw new InvalidOperationException($"Unsupported database evaluation calculation code '{work.CalculationCode}'.")
        };
        var direction=ParseDirection(work.ConfigurationJson);var passed=count>=work.MinimumSampleSize&&(value.HasValue&&(direction=="LOWER_IS_BETTER"?value<=work.TargetValue:value>=work.TargetValue));var status=count<work.MinimumSampleSize?"INSUFFICIENT_DATA":passed?"PASSED":"FAILED";var details=JsonSerializer.Serialize(new{work.MetricCode,direction,work.TargetValue,work.WarningValue,work.MinimumSampleSize});await connection.ExecuteAsync(new CommandDefinition("UPDATE AI.EvaluationRun SET StatusCode=@StatusCode,SampleCount=@SampleCount,MetricValue=@MetricValue,Passed=@Passed,DetailsJson=@Details,CompletedDateUtc=SYSUTCDATETIME(),LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,ModifiedDateUtc=SYSUTCDATETIME() WHERE EvaluationRunId=@Id AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';",new{Id=work.EvaluationRunId,LeaseOwner=leaseOwner,StatusCode=status,SampleCount=count,MetricValue=value,Passed=count>=work.MinimumSampleSize?(bool?)passed:null,Details=details},cancellationToken:cancellationToken));
    }

    private static async Task<(int Count,decimal? Value)> ScalarAsync(IDbConnection connection,EvaluationWork work,string sql,CancellationToken cancellationToken){var result=await connection.QuerySingleAsync<MetricResult>(new CommandDefinition(sql,new{work.TenantId,Start=work.WindowStartUtc,End=work.WindowEndUtc},cancellationToken:cancellationToken));return(result.Count,result.Value);}
    private static string ParseDirection(string? json){if(string.IsNullOrWhiteSpace(json))return "HIGHER_IS_BETTER";using var document=JsonDocument.Parse(json);return document.RootElement.TryGetProperty("direction",out var node)?node.GetString()?.ToUpperInvariant()??"HIGHER_IS_BETTER":"HIGHER_IS_BETTER";}
    private static string Truncate(string value,int max)=>value.Length<=max?value:value[..max];
    private sealed record SettingRow(string SettingKey,string SettingValue);
    private sealed record RecommendationWork(Guid RecommendationWorkItemId,Guid TenantId,string EntityTypeCode,Guid EntityId,string CorrelationId,int AttemptCount,int MaximumAttempts);
    private sealed record RecommendationRuleCondition(Guid RecommendationRuleId,string ConditionJson);
    private sealed record EvaluationWork(Guid EvaluationRunId,Guid? TenantId,DateTime WindowStartUtc,DateTime WindowEndUtc,string MetricCode,string CalculationCode,decimal TargetValue,decimal WarningValue,int MinimumSampleSize,string? ConfigurationJson);
    private sealed record MetricResult(int Count,decimal? Value);
    private sealed record PlatformWork(Guid IntelligenceWorkItemId,Guid TenantId,string CapabilityCode,string WorkTypeCode,int AttemptCount,int MaximumAttempts);
}

public sealed record IntelligenceWorkerSettings(int BatchSize,int PollIntervalSeconds,int LeaseSeconds,int EvaluationIntervalMinutes,int SearchIndexIntervalMinutes,int PlatformBatchSize,int PlatformIntervalSeconds,int PlatformLeaseSeconds);
